"""Generate a self-contained offline dashboard from actual E2E outputs; no CDN/network dependencies."""
import base64
import html
import json
from pathlib import Path

from task2_1_prototype.services.connector_service.validation import safe_asset


def render_dashboard(output, summary, snapshots, images):
    output = Path(output)
    cards = []
    for item in images:
        path = safe_asset(output / "wp1", item["image_ref"])
        encoded = base64.b64encode(path.read_bytes()).decode("ascii")
        label = f'{item["equipment_id"]} · {item["process_id"]} · {item["sim_time_s"]:g}s · {item["stage"]}'
        cards.append(f'<figure><img loading="lazy" alt="{html.escape(label)}" src="data:image/png;base64,{encoded}"><figcaption>{html.escape(label)}<small>合成标签 · {html.escape(item["synthetic_label"])}</small></figcaption></figure>')
    payload = json.dumps({"summary": summary, "snapshots": snapshots}, ensure_ascii=False).replace("<", "\\u003c")
    document = TEMPLATE.replace("__DATA__", payload).replace("__IMAGES__", "".join(cards)).replace("__IMAGE_COUNT__", str(len(images)))
    (output / "e2e_dashboard.html").write_text(document, encoding="utf-8")


